-- Story #987: pincodes seeded from the GeoNames India postal code file (CC BY 4.0, https://download.geonames.org/export/zip/IN.zip, via github.com/sanand0/pincode data/IN.csv): pin, lat, lng only.
-- Part 2 of 2. Rows without a centroid in the file are left out.
-- The one-row table below is this file's marker for the prod apply plan (scripts/prod_backend_v2.py needs one named object per file); the rows are idempotent.
create table if not exists pincodes_seed_2 (loaded_at timestamptz not null default now());
alter table pincodes_seed_2 enable row level security;
revoke all on pincodes_seed_2 from public, anon, authenticated;
on conflict (pin) do nothing;
